function validate([n, edges, distanceThreshold]) {
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is between 2 and 100.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > n * (n - 1) / 2) return 'edges needs between 1 and n * (n - 1) / 2 roads.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each road is [from, to, weight].';
    const [from, to, weight] = edge;
    if (from < 0 || from >= to || to >= n) return 'Each road needs 0 <= from < to < n.';
    if (weight < 1 || weight > 10000) return 'Each weight is between 1 and 10^4.';
    const key = from * 100 + to;
    if (seen.has(key)) return 'Each pair of cities has at most one road.';
    seen.add(key);
  }
  if (!Number.isInteger(distanceThreshold) || distanceThreshold < 1 || distanceThreshold > 10000) return 'distanceThreshold is between 1 and 10^4.';
  return null;
}

