function findTheCity(n, edges, distanceThreshold) {
  const dist = Array.from({ length: n }, () => new Array(n).fill(Infinity));
  for (let i = 0; i < n; i++) {
    dist[i][i] = 0;
  }
  for (const [from, to, weight] of edges) {
    dist[from][to] = weight;
    dist[to][from] = weight;
  }

  for (let k = 0; k < n; k++) {
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (dist[i][k] + dist[k][j] < dist[i][j]) {
          dist[i][j] = dist[i][k] + dist[k][j];
        }
      }
    }
  }

  let bestCity = -1;
  let fewest = Infinity;
  for (let i = 0; i < n; i++) {
    let reachable = 0;
    for (let j = 0; j < n; j++) {
      if (j !== i && dist[i][j] <= distanceThreshold) {
        reachable++;
      }
    }
    if (reachable <= fewest) {
      fewest = reachable;
      bestCity = i;
    }
  }
  return bestCity;
}

