function findTheCity(n, edges, distanceThreshold) {
  // Bellman-Ford from every city: relax every road until nothing changes.
  const counts = [];
  for (let source = 0; source < n; source++) {
    const best = new Array(n).fill(null);
    best[source] = 0;
    let changed = true;
    while (changed) {
      changed = false;
      for (const [u, v, w] of edges) {
        if (best[u] !== null && (best[v] === null || best[u] + w < best[v])) { best[v] = best[u] + w; changed = true; }
        if (best[v] !== null && (best[u] === null || best[v] + w < best[u])) { best[u] = best[v] + w; changed = true; }
      }
    }
    counts.push(best.filter((d, city) => city !== source && d !== null && d <= distanceThreshold).length);
  }
  const least = Math.min(...counts);
  return counts.lastIndexOf(least);
}

