function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 80 + Math.floor(rand() * 21) : 2 + Math.floor(rand() * 6);
  const pairs = [];
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) pairs.push([i, j]);
  for (let i = pairs.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
  }
  const most = large ? Math.min(pairs.length, 2000) : pairs.length;
  const count = large ? Math.floor(most / 4) + Math.floor(rand() * (most - Math.floor(most / 4) + 1)) : 1 + Math.floor(rand() * most);
  const maxWeight = large ? 10000 : (rand() < 0.5 ? 5 : 20);
  const edges = pairs.slice(0, count).map(([from, to]) => [from, to, 1 + Math.floor(rand() * maxWeight)]);
  const distanceThreshold = large ? 1 + Math.floor(rand() * 5000) : 1 + Math.floor(rand() * 2 * maxWeight);
  return [n, edges, distanceThreshold];
}
